/**
 * 赛事信息响应。
 *
 * @param raceId    赛事ID
 * @param version   当前版本号（从1开始）
 * @param status    OPEN / SEALED
 * @param createdAt 创建时间，Unix毫秒时间戳
 */
public record RaceResponse(String raceId, int version, RaceStatus status, long createdAt) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.RaceStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 成绩榜响应：即时成绩或封榜只读快照。
 *
 * @param raceId   赛事ID
 * @param version  榜单对应的版本号
 * @param status   OPEN / SEALED
 * @param sealedAt 封榜时间，Unix毫秒时间戳；未封榜为 null
 * @param entries  按展示顺序排列的成绩条目
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record StandingResponse(
        String raceId,
        int version,
        RaceStatus status,
        Long sealedAt,
        List<ResultEntryResponse> entries
) {
}

